import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadHaiderpurData(){const e=readFileSync(resolve(__dirname,"../../frontend/haiderpur-wetland-explorer/haiderpur-data.js"),"utf-8");return new Function(e+"\nreturn { HAIDERPUR_INFO, ECOLOGY_HYDROLOGY, FAUNA_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Haiderpur Wetland Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadHaiderpurData()}),describe("HAIDERPUR_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.HAIDERPUR_INFO.id).toBe("haiderpur-wetland"),expect(e.HAIDERPUR_INFO.name).toContain("Haiderpur"),expect(e.HAIDERPUR_INFO.ramsarYear).toBe(2021),expect(e.HAIDERPUR_INFO.ramsarSiteNo).toBe(2463),expect(e.HAIDERPUR_INFO.state).toBe("Uttar Pradesh")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.HAIDERPUR_INFO.quickStats)).toBe(!0),expect(e.HAIDERPUR_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, hydrology, biodiversity, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.biodiversity).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("FAUNA_SPECIES catalog",()=>{it("is a non-empty array of fauna species",()=>{expect(Array.isArray(e.FAUNA_SPECIES)).toBe(!0),expect(e.FAUNA_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Swamp Deer (Barasingha) and Sarus Crane",()=>{const t=e.FAUNA_SPECIES.find(e=>"swamp-deer"===e.id),a=e.FAUNA_SPECIES.find(e=>"sarus-crane"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"haiderpur-wetland"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../haiderpur-wetland-explorer/index.html")})})});